      ___SCMOBJ condvars[MAX_CONDVARS];
      ___SCMOBJ condvar;
      int event_pos = 0;
      int write_pos = 0;
      int read_pos = 0;
      int i;
      int j;

      condvar = ___BTQ_DEQ_NEXT_FIELD(devices);

      while (condvar != devices)
        {
          ___SCMOBJ owner = ___BTQ_OWNER_FIELD(condvar);
          if (read_pos < MAX_CONDVARS-1)
            {
              ___BTQ_OWNER_FIELD(condvar) = owner & ~___FIX(1);
              switch (___INT(owner)>>1)
                {
                case FOR_READING:
                  condvars[read_pos++] = condvar;
                  break;
                case FOR_WRITING:
                  condvars[read_pos++] = condvars[write_pos];
                  condvars[write_pos++] = condvar;
                  break;
                case FOR_EVENT:
                  condvars[read_pos++] = condvars[write_pos];
                  condvars[write_pos++] = condvars[event_pos];
                  condvars[event_pos++] = condvar;
                  break;
                }
            }
          else
            {
              ___BTQ_OWNER_FIELD(condvar) = owner | ___FIX(1);
              to = ___time_mod.time_neg_infinity;
            }
          condvar = ___BTQ_DEQ_NEXT_FIELD(condvar);
