      e = ___device_select (devs,
                            read_pos - write_pos,
                            write_pos - event_pos,
                            event_pos,
                            to);

      ___PRIMITIVELOCK(devices,___FIX(___OBJ_LOCK1),___FIX(___OBJ_LOCK2))

      for (i=0; i<read_pos; i++)
        {
